import json
from pathlib import Path

def request(path):
    body = {"/v1/title": {"legacy_title": "Report"}, "/v2/title": {"title": "Report"}, "/balance": {"balance": 12}}
    if path not in body:
        return 404, {}, {}
    markers = json.loads(Path(__file__).with_name("deprecations.json").read_text())
    headers = {}
    if path in markers:
        headers = {"Deprecation": "true", "Sunset": markers[path]["sunset"], "Link": markers[path]["replacement"]}
    return 200, body[path], headers

